local _, WFI = ...
WFI.Data.add("quest", {
  [4161] = { "Una ricetta dei kaldorei", "Raccogli 7 Small Spider Legs per Zarrin, a Dolanaar.", "Tanto tempo fa gli elfi della notte si chiamavano kaldorei, un nome che significa \"figli delle stelle\". Conoscere il passato è un passo importante nel tuo cammino di {class}, {name}, quindi ascolta bene quello che ho da dirti.\n\nI kaldorei sono sempre stati molto orgogliosi del loro rapporto armonioso con la natura. Questo vuol dire che prendiamo dalla natura solo il necessario, e che restituiamo altrettanto. Questo equilibrio ci ha dato molto, {name}.\n\nVai a raccogliere sette Small Spider Legs, non di più, e torna da me.", "Ricorda l'equilibrio, {name}. Voglio che tu sviluppi comprensione e una forte empatia per le foreste viventi.", "Ricorda sempre quello che ti ho mostrato oggi, {name}. Fai parte dell'equilibrio che gli elfi della notte cercano di mantenere intatto, anche nei tempi difficili.", 0xc790841a, 0x7c7f5405, 0x2a2ed2f9, 0xb7a98f7e, 0xbe9fad73, "....." },
  [4183] = { "I veri padroni", nil, nil, nil, nil, 0xbd06798d, nil, nil, nil, nil, ".mmmm" },
  [4184] = { "I veri padroni", "Vai a Stormwind e consegna la Solomon's Plea a Highlord Bolvar Fordragon.\n\nBolvar risiede nella Stormwind Keep.", "Sono notizie cupe, {name}. Scoprire che i nostri nemici mortali sono solo pedine di una minaccia molto più grande è scoraggiante. Lakeshire non potrebbe mai sopravvivere a un attacco sia degli orchi Blackrock sia del black dragonflight. Se Lakeshire cadesse davanti a questa minaccia, poi toccherebbe a Darkshire, e dopo? Goldshire? Stormwind stessa?\n\nDevi portare subito queste informazioni a Highlord Bolvar Fordragon, a Stormwind! Se questo non basta a ottenere l'aiuto di Stormwind, niente basterà, e tutto è perduto.", "Cosa ti porta alla Stormwind Keep?", "Draghi? Impossibile!", 0xbd06798d, 0x7d939500, 0x5a607832, 0x46dba375, 0xdc21b8a7, "....." },
  [4185] = { "I veri padroni", nil, nil, nil, nil, 0xbd06798d, nil, nil, nil, nil, ".mmmm" },
  [4186] = { "I veri padroni", nil, nil, nil, nil, 0xbd06798d, nil, nil, nil, nil, ".mmmm" },
  [4223] = { "I veri padroni", "Parla con Marshal Maxwell, nelle Burning Steppes.", "<Magistrate Solomon sospira.>\n\nDevi tornare nelle Burning Steppes, {name}. Come vicesceriffo di Stormwind, dovrai fare rapporto a Marshal Maxwell. Buona fortuna.", nil, "<Marshal Maxwell ride.>", 0xbd06798d, 0xb198a748, 0x6a799072, nil, 0xc32699c8, "...m." },
  [4224] = { "I veri padroni", nil, nil, nil, nil, 0xbd06798d, nil, nil, nil, nil, ".mmmm" },
  [4485] = { nil, "Parla con Duthorian Rall, a Stormwind.", nil, nil, nil, nil, 0x0f3ca705, nil, nil, nil, "m.mmm" },
  [4486] = { nil, "Parla con Duthorian Rall, a Stormwind.", nil, nil, nil, nil, 0x0f3ca705, nil, nil, nil, "m.mmm" },
  [4493] = { "La marcia dei silithid", "Parla con Alchemist Pestlezugg, a Gadgetzan.", "Sembra che l'intento dei silithid, anzi, la loro ragion d'essere, sia divorare tutto ciò che incontrano e che non appartiene al loro ecosistema. Hanno un unico scopo, ed è per questo che sono una grave minaccia per tutta la vita su Azeroth.\n\nQuello che abbiamo visto finora è solo l'inizio. Sospetto che la loro forza venga dal cuore di Kalimdor: l'Un'Goro Crater. Vai a Gadgetzan, nel deserto di Tanaris, e parla con Alchemist Pestlezugg. Raccontagli la mia teoria; di sicuro ci aiuterà a combattere i silithid.", nil, "Sì, avevo capito che ti mandava Gracina. La tua esperienza nel combattere queste bestiacce non ha prezzo; per quanto ne so, nessuno aveva mai avuto a che fare con quelle creature prima. Quanto all'idea di Gracina che il loro cuore sia l'Un'Goro Crater... forse è così. Un'Goro è una giungla misteriosa e pericolosa a ovest di qui. Forse è anche un passo più vicino a capire cosa sono davvero i silithid.", 0x38486200, 0x2fa7b4e6, 0xff4ae737, nil, 0x2146fcf0, "...m." },
  [4494] = { "La marcia dei silithid", "Parla con Alchemist Pestlezugg, a Gadgetzan.", "Sembra che l'intento dei silithid, anzi, la loro ragion d'essere, sia divorare tutto ciò che incontrano e che non appartiene al loro ecosistema. Hanno un unico scopo, ed è per questo che sono una grave minaccia per tutta la vita su Azeroth.\n\nQuello che abbiamo visto finora è solo l'inizio. Sospetto che la loro forza venga dal cuore di Kalimdor: l'Un'Goro Crater. Vai a Gadgetzan, nel deserto di Tanaris, e parla con Alchemist Pestlezugg. Raccontagli la mia teoria; di sicuro ci aiuterà a combattere i silithid.", nil, nil, 0x38486200, 0x2fa7b4e6, 0xff4ae737, nil, nil, "...mm" },
  [4495] = { "Un buon amico", "Trova Iverron vicino alla caverna a nord.", "Un mio amico di nome Iverron di solito viene a trovarmi ogni giorno alla stessa ora. Il fatto strano è che oggi non si è proprio visto: anzi, è in ritardo di diverse ore.\n\nLo ammetto, sono un po' preoccupata, {name}. Iverron passa molto tempo vicino alla caverna a nord, e di sicuro sai quanto è pericolosa: ragni dappertutto!\n\nSe però per caso vai da quella parte, terresti gli occhi aperti per lui?", nil, "Sono così felice che tu mi abbia trovata, {name}. Come sapevi che ero qui?", 0xc68e1991, 0xa973ef17, 0xfa034016, nil, 0x8083d57b, "...m." },
  [4508] = { "La quiete prima della tempesta", nil, nil, nil, nil, 0x2a848062, nil, nil, nil, nil, ".mmmm" },
  [4509] = { "La quiete prima della tempesta", nil, nil, nil, nil, 0x2a848062, nil, nil, nil, nil, ".mmmm" },
  [4510] = { "La quiete prima della tempesta", "Porta il Bank Voucher a Idriana, nella banca di Darnassus.", "{name}, il tuo aiuto è stato inestimabile. Verrà il momento, senza dubbio, in cui ti chiederò di nuovo aiuto contro i silithid. Dobbiamo assimilare ciò che abbiamo imparato a Un'Goro; temo che le mie supposizioni sull'origine dei silithid a Un'Goro siano sbagliate... che ci sia davvero una presenza molto più forte da qualche parte.\n\nPorta questo biglietto a Idriana, alla banca. Ti darà qualcosa dal mio caveau, da considerare un segno della mia gratitudine. Grazie per il tuo aiuto, prode {class}.", "Elune'adore, {class}. Cosa posso fare per te oggi?", "Questo buono bancario mi autorizza a prelevare un oggetto dal conto di Gracina Spiritmight presso di noi e a consegnarlo a te. Direi che sono d'obbligo le congratulazioni!", 0x2a848062, 0xc67f689d, 0xbe332e09, 0xd9a6df82, 0xd0305231, "....." },
  [4511] = { "La quiete prima della tempesta", nil, nil, nil, nil, 0x2a848062, nil, nil, nil, nil, ".mmmm" },
  [4681] = { "Portati a riva", "Recupera i Sea Turtle Remains dalla Skeletal Sea Turtle nelle acque a ovest di Auberdine, poi parla con Gwennyth Bly'Leggonde ad Auberdine.", "Quella creatura spiaggiata non è un caso isolato qui a Darkshore. Ce ne sono altre lungo la costa e persino in acqua. Vorrei che ne esaminassi un'altra che conosciamo; questa è stata segnalata in acqua, proprio a ovest di Auberdine, vicino a una nave affondata. Torna da me con qualunque cosa tu riesca a recuperare che possa aiutare le nostre ricerche.\n\nE durante i tuoi viaggi potresti trovare altre creature. Se scopri qualcosa, non esitare a farcelo sapere!", "Una volta che avrai esaminato i resti della creatura nell'acqua a ovest di qui, dovrei poter presentare un rapporto adeguato al Temple of the Moon di Darnassus. Forse allora saremo più vicini a scoprire perché queste sfortunate creature scelgono di porre fine alla loro vita arenandosi sulla costa di Darkshore.", "Oggi ci sei <stato/stata> di enorme aiuto; ora abbiamo una buona possibilità di svelare il mistero del perché queste creature si arenino sulla costa di Darkshore. L'idea che possano fuggire dalla zona intorno a Teldrassil è inquietante. Se ne incontrassi altre nei tuoi viaggi, fammelo sapere. Le nostre ricerche sono solo agli inizi.\n\nA nome del Temple of the Moon, accetta questo come ringraziamento per il tuo impegno. Grazie, {name}!", 0x8079e34a, 0x149950e7, 0xcc7a3f7b, 0x32bf10da, 0xa60fc069, "....." },
  [4722] = { "Una tartaruga marina spiaggiata", "Porta i Sea Turtle Remains a Gwennyth Bly'Leggonde, ad Auberdine.", "Trovi il cadavere di una tartaruga marina che si è arenata sulla costa di Darkshore tempo fa. È stato spolpato dai murloc che si sono accampati intorno ai resti della creatura. Eppure sembrano rimasti campioni adatti sui resti, che Gwennyth Bly'Leggonde, ad Auberdine, potrebbe usare.", "Salve, {name}. Hai scoperte da riferire su creature arenate sulla riva?", "Un'altra scoperta da studiare: ben fatto, {name}! Questi resti saranno studiati come si deve una volta arrivati a Darnassus. Accetta questo piccolo compenso in cambio dei resti che ci hai fornito per il nostro studio.", 0x3b1c0992, 0xb04a5a8b, 0x3d413149, 0x1ac8bd61, 0x9e7fd774, "....." },
  [4723] = { "Una creatura marina spiaggiata", "Porta le Sea Creature Bones a Gwennyth Bly'Leggonde, ad Auberdine.", "I resti di un thresher gigante, molto più grande di quanto ci si aspetterebbe di trovarne a Darkshore, giacciono arenati sulla costa del Mist's Edge. Come questa creatura sia arrivata qui non si sa; il gruppo di murloc che ora banchetta con la sua carcassa sembra troppo debole, anche in gran numero, per aver abbattuto la bestia.\n\nAnche se in parte è stata ripulita, ne resta abbastanza per prelevare un campione per gli studi di Gwennyth Bly'Leggonde, ad Auberdine.", "Forse un giorno troveremo un modo per impedire a queste povere creature di porre fine inutilmente alla loro vita sulla costa di Darkshore. Fino ad allora, dobbiamo continuare le nostre ricerche!\n\nSalve, {name}. Quali notizie porti?", "Un'altra scoperta: ben fatto, {name}! Questi resti saranno studiati come si deve una volta arrivati a Darnassus. Accetta questo piccolo compenso in cambio dei resti che ci hai fornito per il nostro studio.", 0x4bb68b2b, 0xc0ba3e69, 0x9a0bf524, 0x919b7748, 0x3513dc87, "....." },
  [4725] = { "Una tartaruga marina spiaggiata", "Porta la Strangely Marked Box a Gwennyth Bly'Leggonde, ad Auberdine.", "Altri resti di tartaruga marina giacciono arenati lungo la costa. A questo guscio è attaccato un carro abbandonato. Forse questa creatura è stata spinta a riva da esseri sconosciuti, invece di arenarsi da sola come suggerivano alcuni degli altri resti. Ora i murloc Greymist hanno fatto dei resti di questa creatura la loro casa, e si nutrono della carogna.\n\nNel carro trovi una scatola con strani segni; forse Gwennyth Bly'Leggonde, ad Auberdine, saprà capirci qualcosa.", "È un piacere rivederti, {name}. Stiamo facendo grandi passi avanti nello svelare il mistero del perché maestose creature marine si arenino sulle coste di Darkshore, ma sembra che per ogni domanda che trova risposta ne sorgano altre due.\n\nSei qui per offrirci altro aiuto nelle nostre ricerche?", "Ho sentito parlare del tipo di carri trovati sul dorso della tartaruga che hai scoperto. Credo proprio che siano carri naga, usati sia in battaglia sia per trasportare i rifornimenti sulla terraferma. I segni sulla scatola che hai trovato sono dei naga; questo spiegherebbe la loro presenza invasiva nell'estremo nord di Darkshore.\n\nManderò questa scatola a Darnassus insieme al resto delle tue scoperte. Questo è per te: grazie ancora per il tuo aiuto.", 0x3b1c0992, 0xe042fc30, 0xbf35a518, 0xeaee6b01, 0x3dd5d2a8, "....." },
  [4727] = { "Una tartaruga marina spiaggiata", "Porta i Sea Turtle Remains a Gwennyth Bly'Leggonde, ad Auberdine.", "I resti scheletrici di una tartaruga marina giacciono nella sabbia delle spiagge settentrionali di Darkshore. I murloc Greymist o non hanno trovato questa carcassa, o forse l'hanno trovata e la evitano per qualche motivo sconosciuto. In ogni caso, della tartaruga ne resta abbastanza per riportare un campione a Gwennyth Bly'Leggonde, ad Auberdine, perché il Temple of the Moon lo studi.", "Salve di nuovo, {name}. Hai trovato altre creature arenate di cui il Temple of the Moon dovrebbe essere informato?", "È interessante che i murloc non fossero presenti in questo luogo; lo terremo a mente mentre studiamo i resti di questa creatura! Grazie per il tuo impegno, {name}; il Temple of the Moon desidera che ti dia questo, come compenso per il tuo tempo.", 0x3b1c0992, 0xb04a5a8b, 0x571231c8, 0x7d319b8f, 0x07b7db83, "....." },
  [4728] = { "Una creatura marina spiaggiata", "Porta le Sea Creature Bones a Gwennyth Bly'Leggonde, ad Auberdine.", "Il cadavere di quello che sembra un gigantesco mammifero marino giace in parte sventrato sulla spiaggia. Una carriola e vari attrezzi sono abbandonati accanto a questa enorme creatura spiaggiata, come se qualcuno avesse già provato a studiarla. Anche se i murloc hanno banchettato con la bestia, ne resta abbastanza per raccogliere un campione adatto per Gwennyth Bly'Leggonde, ad Auberdine.", "Salve di nuovo, {name}! Cosa ti riporta ad Auberdine? Sei qui per riferire un'altra scoperta, forse?", "Ah, credo che tu ne abbia scoperta una che inizialmente veniva esaminata dall'Explorer's League. Sono presenti qui a Darkshore e avevano detto di studiare una delle creature arenate finché non sono stati cacciati dai murloc. A quanto pare sei <riuscito/riuscita> dove noi due abbiamo fallito. Ti prego, accetta questo compenso a nome del Temple of the Moon.", 0x4bb68b2b, 0xc0ba3e69, 0xb92ea900, 0x2d08586e, 0xc17c3fc8, "....." },
  [4730] = { "Una creatura marina spiaggiata", "Porta le Sea Creature Bones a Gwennyth Bly'Leggonde, ad Auberdine.", "Il cadavere mezzo divorato di quello che forse era un gigantesco mammifero marino giace sulla spiaggia. Una banda di murloc, più forti di quelli che si trovano vicino ad Auberdine, si è stabilita intorno alla creatura caduta. Ne resta abbastanza per consegnare un campione adatto delle sue ossa a Gwennyth Bly'Leggonde, ad Auberdine.", "Salve di nuovo, {name}! Sei qui per riferire un'altra scoperta?", "Le ossa che hai provengono da miti mammiferi marini noti per abitare le acque intorno alla base di Teldrassil. Non si era mai saputo che si arenassero violentemente come invece facevano i thresher. Perché queste creature lo farebbero, mi chiedo? Beh, forse lo studio dei loro resti darà i frutti di conoscenza che cerchiamo.\n\nGrazie ancora per il tuo aiuto. Accetta questo compenso da parte del Temple of the Moon.", 0x4bb68b2b, 0xc0ba3e69, 0xe841063a, 0xd044bb6e, 0x6ea9c612, "....." },
  [4731] = { "Una tartaruga marina spiaggiata", "Porta la Strangely Marked Box a Gwennyth Bly'Leggonde, ad Auberdine.", "Altri resti di tartaruga marina giacciono arenati sulla costa. Questi resti hanno un carro abbandonato mezzo agganciato al guscio della tartaruga. Forse questa creatura è stata spinta a riva da esseri sconosciuti, invece di arenarsi da sola come suggerivano alcuni degli altri resti. Potenti murloc Greymist hanno fatto della carcassa di questa creatura la loro casa attuale.\n\nNel carro trovi una scatola con strani segni; forse Gwennyth Bly'Leggonde, ad Auberdine, saprà capirci qualcosa.", "Salve di nuovo, {name}. Il lavoro che hai svolto per il Temple of the Moon è stato eccezionale. Saremo benedetti da altri tuoi sforzi in nostro favore?", "Ho sentito parlare del tipo di carri trovati sul dorso di quella tartaruga. Credo proprio che siano carri naga, usati sia in battaglia sia per trasportare i rifornimenti sulla terraferma. I segni sulla scatola che hai trovato sono dei naga; forse la creatura che hai scoperto è stata uccisa mentre si dirigeva più a sud... forse verso Ashenvale?\n\nMi assicurerò di mandare questa scatola a Darnassus con il resto delle tue scoperte. Questo è per te: grazie ancora per il tuo aiuto.", 0x3b1c0992, 0xe042fc30, 0x8653ac9e, 0x69e011cf, 0xb192bb2e, "....." },
  [4732] = { "Una tartaruga marina spiaggiata", "Porta i Sea Turtle Remains a Gwennyth Bly'Leggonde, ad Auberdine.", "Trovi il cadavere di una tartaruga marina che si è arenata sulla costa di Darkshore tempo fa. È stato spolpato quasi del tutto dai murloc Greymist, proprio quelli che ora si sono accampati intorno ai resti della creatura. Eppure sembrano rimasti campioni adatti sui resti, che Gwennyth Bly'Leggonde, ad Auberdine, potrebbe usare.", "Salve di nuovo, {name}. Hai altre scoperte da riferire al Temple of the Moon?", "Hai trovato altre creature arenate, {name}? Le tartarughe marine si vedevano spesso giocare lungo la base di Nordrassil prima che fosse distrutto. Con la nascita di Teldrassil, però, queste creature si sono viste in numero sempre minore. Alcune, come abbiamo scoperto, pongono fine alla loro vita qui per qualche motivo sconosciuto.\n\nIl tuo aiuto forse svelerà il mistero che abbiamo davanti. Accetta questo in cambio dei resti che ci hai fornito per il nostro studio.", 0x3b1c0992, 0xb04a5a8b, 0x149a42d1, 0x068b830b, 0x96ba0af6, "....." },
  [4733] = { "Una creatura marina spiaggiata", "Porta le Sea Creature Bones a Gwennyth Bly'Leggonde, ad Auberdine.", "I resti di quello che sembra un thresher gigante sono finiti a riva sull'insenatura rocciosa della Twilight Shore. Il thresher è diverse volte più grande di tutti gli altri thresher avvistati da queste parti. Da qualunque posto venga, questa creatura non sembra originaria di Darkshore.\n\nAnche se in alcuni punti la creatura è stata fatta a pezzi, ne resta abbastanza per raccogliere un campione adatto per Gwennyth Bly'Leggonde, ad Auberdine.", "Sia ringraziata Elune: sono lieta di rivederti, <caro/cara> {name}. Il lavoro del Temple of the Moon sullo strano fenomeno degli spiaggiamenti continua qui a Darkshore. Hai qualcos'altro da offrirci?", "Le dimensioni del thresher di cui parli sono sbalorditive. Persino i thresher più vecchi di questa regione raggiungono solo una frazione di quella taglia. Anche se si sapeva che alcuni più grandi vivevano vicino a Teldrassil, il loro numero è diminuito costantemente. Non posso fare a meno di chiedermi se il fatto che queste creature si arenino qui sia in qualche modo collegato.\n\nMentre analizziamo le ossa che ci hai portato, accetta questo a nome del Temple of the Moon. Grazie, {name}.", 0x4bb68b2b, 0xc0ba3e69, 0x88008738, 0x2ba63290, 0xa5eb453e, "....." },
  [4740] = { "RICERCATO: Murkdeep!", "Trova e uccidi il murloc noto come Murkdeep. Si pensa che difenda le capanne dei murloc a sud di Auberdine, lungo l'acqua.\n\nRiferisci la morte di Murkdeep a Sentinel Glynda Nal'Shea, ad Auberdine.", "Attenzione!\n\nÈ offerta una ricompensa per la morte del murloc \"Murkdeep\". Questa lurida bestia è responsabile della morte di almeno una Sentinel, ed è sospettata di aver fatto affondare almeno due navi da carico nelle acque al largo di Darkshore!\n\nMurkdeep è stato avvistato l'ultima volta in un accampamento di capanne dei murloc a sud di Auberdine, e si pensa che protegga le capanne. La ricompensa va reclamata presso Sentinel Glynda Nal'Shea, ad Auberdine.\n\nThe Auberdine Village Council", "Salve, {class}. In cosa possono assisterti le Sentinels oggi? Forse sei qui per informarti sulla taglia su Murkdeep?", "Beh, sembra che tu sia qui per qualcosa di più che informarti! I cittadini saranno felici di sapere che stanotte dormiranno un po' più tranquilli e al sicuro.\n\nOggi hai fatto da esecutore della giustizia per la gente di Auberdine, {name}. Per questo vorrei offrirti questo come degna ricompensa... per un vero eroe del popolo di Auberdine.", 0xcf1b7374, 0xd0180f37, 0x68da692c, 0x1e209309, 0xb1230932, "....." },
  [4761] = { nil, "Parla con Thundris Windweaver, ad Auberdine.", "Le informazioni sulla tua esplorazione dell'accampamento dei furbolg vanno riferite a Thundris Windweaver. È gentilmente l'anziano di Auberdine, e guida con saggezza e giustizia gli affari quotidiani del villaggio. Ti prego, condividi con lui ciò che hai scoperto finora sulla situazione dei furbolg.\n\nCredo che abbia qualche idea sua sulle cause della loro corruzione. Forse potrai lavorare con lui a un piano per ristabilire qui l'equilibrio della natura!", nil, "Ben <trovato/trovata>, {class}. La tua ricognizione sulla situazione dei furbolg arriva in un momento propizio per noi di Auberdine. Da tempo abbiamo a che fare non solo con abitanti della foresta ora apertamente ostili alla nostra presenza, ma anche con la corruzione vera e propria della foresta stessa. Speriamo che tu possa aiutare Auberdine in questi tempi difficili.", nil, 0xe04eac93, 0x5978da41, nil, 0x8e442694, "m..m." },
  [4762] = { "Il Cliffspring River", "Vai a nord di Auberdine fino alla prima cascata lungo il Cliffspring River e preleva un campione dalla pozza.\n\nTorna da Thundris Windweaver ad Auberdine con il Cliffspring River Sample.", "Il Cliffspring River ha cominciato a diventare torbido e corrotto. Sfocia nel Mist's Edge, e temo che presto le sue acque colpiranno Auberdine. Sospetto che la causa della contaminazione siano i furbolg Blackwood a monte, ma sospetto anche che non siano loro la vera radice.\n\nPrendi questa provetta e vai alla foce del fiume, a nord. Risali verso l'interno fino alla prima cascata e preleva un campione dalla pozza. Vedrai un ponte sopra di te. Quando avrai il campione, torna da me ad Auberdine.", "L'inquinamento del Cliffspring River è solo l'inizio di una tendenza allarmante qui a Darkshore. Il campione che fornirai ci aiuterà a definire un piano... un piano d'attacco, comincio a sospettare.", "Non sorprende quanto sia contaminata quest'acqua, ma guarda quanto sta diventando putrida! Sembra che sia necessario agire prima piuttosto che poi, eh, {name}?\n\nA est di qui c'è Felwood; è la vera fonte di questa corruzione, una corruzione che ho già visto in passato. Prevedo che questo campione lo confermerà. Potremmo riuscire a trovare una cura qui, ma anche solo per tentare avremo bisogno di aiuto. Quando verrà il momento, {name}, spero che potrai darci l'aiuto di cui abbiamo bisogno.", 0x732408df, 0x9c875372, 0x31c4d12c, 0xcd07cafd, 0x405bb8d6, "....." },
  [4763] = { "I Blackwood corrotti", "Riempi l'Empty Cleansing Bowl al pozzo lunare di Auberdine.\n\nRaccogli un campione di frutta, di noci e di grano dagli accampamenti settentrionali dei furbolg Blackwood.\n\nMescola il contenuto della ciotola e mettila vicino al falò più vicino al Cliffspring River, nell'accampamento settentrionale, per evocare il satiro corruttore.\n\nPrendi il Talisman of Corruption e portalo a Thundris Windweaver, ad Auberdine.", "Abbiamo scoperto che una fonte della corruzione dei furbolg sono i satiri. Li dominano tramite talismani attraverso cui incanalano la magia. Se i furbolg hanno una possibilità di salvezza, dobbiamo attirare fuori il satiro corruttore e prendere quel talismano!\n\nRiempi questa ciotola al nostro pozzo lunare e prendi campioni del cibo dei furbolg dal loro accampamento settentrionale. Mescolali e mettili vicino al falò accanto al fiume; i furbolg che ne mangeranno saranno purificati quanto basta per attirare fuori il satiro corruttore... che poi dovrai uccidere!", "Il Talisman of Corruption è un congegno sinistro che serve solo a pervertire l'equilibrio della natura. Quando avrai ottenuto questo oggetto dal satiro che tormenta i furbolg e me lo porterai perché lo distrugga, oggi avremo ottenuto una grande vittoria!", "Abbiamo appena cominciato questa guerra per riconquistare la nostra foresta dalle forze della corruzione, ma oggi abbiamo vinto una battaglia! {name}, la gente di Auberdine ha con te un debito di gratitudine che non sarà facile ripagare. Accetta questo insieme ai nostri ringraziamenti. Ciò che abbiamo imparato oggi potrebbe un giorno liberare per sempre i nostri amici furbolg dalle catene del tormento.", 0x2f8f88d9, 0xbffe0b22, 0xb9e3e349, 0x893d1d9e, 0xa947b3e7, "....." },
  [4811] = { "Il cristallo rosso", "Vai a est di Auberdine e cerca un grosso cristallo rosso lungo la catena montuosa orientale di Darkshore. Riferisci ciò che trovi a Sentinel Glynda Nal'Shea, ad Auberdine.", "A est di qui si aggirano moonkin ostili in numero sempre crescente. Un tempo erano considerati creature gentili, quasi mistiche. Anche se alcuni continuano a venerarli, la sicurezza di Auberdine mi costringe ad avere una visione più realistica.\n\nMi è stato riferito che i moonkin sono attirati da un grosso cristallo rosso lungo la catena montuosa orientale di Darkshore. Nessuno ha idea di cosa sia quel cristallo, e nemmeno se esista davvero. Voglio che tu lo trovi laggiù e mi riferisca cosa scopri.", "Cosa hai da riferire su quel cristallo rosso? Esiste davvero?", "Quindi il cristallo esiste, {name}? Affascinante... comunque, il tuo compito è stato svolto bene; ottimo lavoro!\n\nChe cos'è esattamente questo cristallo? È solo una domanda in un mare di domande. Un'altra che mi viene in mente è perché i moonkin siano attratti da questo oggetto. Il cristallo è di natura benigna, o ha uno scopo più sinistro?\n\nHo molte altre domande, ma dovremo esaminare quel cristallo da vicino per avere qualche risposta.", 0x5ae7f813, 0x8d4ec0d3, 0x69995f12, 0x84875e53, 0xe63afa83, "....." },
  [4812] = { "Mentre l'acqua scorre", "Riempi l'Empty Water Tube al pozzo lunare di Auberdine, poi esamina il cristallo rosso lungo la parete montuosa orientale di Darkshore.", "Usa questa fiala vuota e riempila con un po' d'acqua del pozzo lunare qui ad Auberdine. Una magia così potente dovrebbe darci un indizio sulla composizione del cristallo. Per farlo, versa il liquido sul cristallo; al resto dovrebbe pensarci lui.\n\nAnche se non prevedo che ti succeda niente di brutto, voglio comunque che tu stia <attento/attenta>. Sopra di noi, a est, c'è Felwood; se quel cristallo è legato a quel posto come sospetto, potrebbe rivelarsi molto pericoloso.", "Il cristallo appare molto alieno sullo sfondo dei boschi di Darkshore. Ti sembra di sentire un ronzio lievissimo provenire dal suo interno.", "Hai raggiunto ancora una volta il misterioso cristallo. Tolto il tappo dalla provetta d'acqua del pozzo lunare, ne versi con cautela il contenuto sulla sommità del cristallo. Mentre l'acqua scorre lungo i suoi reticoli, vedi la superficie opaca diventare trasparente...", 0xdefb4541, 0xe834c2df, 0x29e90dd5, 0xb62a1acf, 0x9b8b44cb, "....." },
  [4813] = { "I frammenti all'interno", "Riferisci ciò che hai trovato a Sentinel Glynda Nal'Shea, ad Auberdine.", "L'acqua del pozzo lunare ha rivelato che dentro il cristallo sono incastonati alcuni piccoli frammenti d'osso, oltre a metà di una mascella. La mascella sembra appartenere a un umanoide, ma non è chiaro senza rompere il cristallo, un'impresa che persino la magia più potente troverebbe quasi impossibile.\n\nPortato a termine il compito, non resta che fare rapporto a Sentinel Glynda Nal'Shea, ad Auberdine.", nil, "Beh, sembra che, anche se ora sappiamo di più su questo cristallo, il risultato siano altre domande senza risposta!\n\nPorterò le informazioni che hai scoperto al consiglio qui ad Auberdine. Forse sapranno quale linea d'azione seguire riguardo a questo cristallo. Sempre che ce ne sia una da intraprendere; per ora la minaccia resta abbastanza lontana a est da non nuocerci.\n\nQuanto a te, prendi questo. Consideralo una ricompensa per un lavoro ben fatto, {name}.", 0xb84b9e71, 0x336ce815, 0x1453b5e8, nil, 0xd3015ad0, "...m." },
  [4902] = { "I wildkin di Elune", "Parla con Arch Druid Fandral Staghelm, a Darnassus.", "Affascinante!\n\nMi sono sempre chiesto quale fosse la verità... Be', devi assolutamente condividere questa scoperta! Vai subito da Arch Druid Fandral Staghelm: lo trovi a Darnassus, nel Cenarion Circle. Spiegagli cosa è successo, proprio come l'hai raccontato a me. Sono sicuro che sarà altrettanto interessato!\n\nSono informazioni importanti, {name}!", nil, "Non esitare; dimmi perché sei <venuto/venuta>.\n\nAh, sì? Mmm. Be'.\n\nGrazie per averlo portato direttamente a me; è sempre meglio rivolgersi ai vertici... Ma... Sì. I druidi del Cenarion Circle conoscono i wildkin da un po' di tempo. Sanno che sono creature di Elune, scelte per sorvegliare i luoghi più sacri.\n\nQuindi, anche se non è una novità, mi complimento di certo per il tuo impegno. Tieni, prendi questo: mi sembra adatto a un'impresa simile.", 0x1fa3452e, 0xf466e7fe, 0xd56e78fc, nil, 0x14e16654, "...m." },
})
